    RegisterActivityTypeInput.add_member(:version, Smithy::Schema::Shapes::ShapeRef.new(shape: Version, location_name: 'version', traits: {"smithy.api#documentation" => "<p>The version of the activity type.</p>\n         <note>\n            <p>The activity type consists of the name and version, the combination of which must be\n        unique within the domain.</p>\n         </note>\n         <p>The specified string must not contain a\n        <code>:</code> (colon), <code>/</code> (slash), <code>|</code> (vertical bar), or any\n      control characters (<code>\\u0000-\\u001f</code> | <code>\\u007f-\\u009f</code>). Also, it must\n      <i>not</i> be the literal string <code>arn</code>.</p>", "smithy.api#required" => {}}))
    RegisterActivityTypeInput.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: Description, location_name: 'description', traits: {"smithy.api#documentation" => "<p>A textual description of the activity type.</p>"}))
    RegisterActivityTypeInput.add_member(:default_task_start_to_close_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: DurationInSecondsOptional, location_name: 'defaultTaskStartToCloseTimeout', traits: {"smithy.api#documentation" => "<p>If set, specifies the default maximum duration that a worker can take to process tasks\n      of this activity type. This default can be overridden when scheduling an activity task using\n      the <code>ScheduleActivityTask</code>\n            <a>Decision</a>.</p>\n         <p>The duration is specified in seconds, an integer greater than or equal to\n        <code>0</code>. You can use <code>NONE</code> to specify unlimited duration.</p>"}))
    RegisterActivityTypeInput.add_member(:default_task_heartbeat_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: DurationInSecondsOptional, location_name: 'defaultTaskHeartbeatTimeout', traits: {"smithy.api#documentation" => "<p>If set, specifies the default maximum time before which a worker processing a task of\n      this type must report progress by calling <a>RecordActivityTaskHeartbeat</a>. If\n      the timeout is exceeded, the activity task is automatically timed out. This default can be\n      overridden when scheduling an activity task using the <code>ScheduleActivityTask</code>\n            <a>Decision</a>. If the activity worker subsequently attempts to record a heartbeat\n      or returns a result, the activity worker receives an <code>UnknownResource</code> fault. In\n      this case, Amazon SWF no longer considers the activity task to be valid; the activity worker should\n      clean up the activity task.</p>\n         <p>The duration is specified in seconds, an integer greater than or equal to\n        <code>0</code>. You can use <code>NONE</code> to specify unlimited duration.</p>"}))
    RegisterActivityTypeInput.add_member(:default_task_list, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskList, location_name: 'defaultTaskList', traits: {"smithy.api#documentation" => "<p>If set, specifies the default task list to use for scheduling tasks of this activity\n      type. This default task list is used if a task list isn't provided when a task is scheduled\n      through the <code>ScheduleActivityTask</code>\n            <a>Decision</a>.</p>"}))
    RegisterActivityTypeInput.add_member(:default_task_priority, Smithy::Schema::Shapes::ShapeRef.new(shape: TaskPriority, location_name: 'defaultTaskPriority', traits: {"smithy.api#documentation" => "<p>The default task priority to assign to the activity type. If not assigned, then\n        <code>0</code> is used. Valid values are integers that range from Java's\n        <code>Integer.MIN_VALUE</code> (-2147483648) to <code>Integer.MAX_VALUE</code> (2147483647).\n      Higher numbers indicate higher priority.</p>\n         <p>For more information about setting task priority, see <a href=\"https://docs.aws.amazon.com/amazonswf/latest/developerguide/programming-priority.html\">Setting Task\n        Priority</a> in the <i>in the\n      <i>Amazon SWF Developer Guide</i>.</i>.</p>"}))
    RegisterActivityTypeInput.add_member(:default_task_schedule_to_start_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: DurationInSecondsOptional, location_name: 'defaultTaskScheduleToStartTimeout', traits: {"smithy.api#documentation" => "<p>If set, specifies the default maximum duration that a task of this activity type can\n      wait before being assigned to a worker. This default can be overridden when scheduling an\n      activity task using the <code>ScheduleActivityTask</code>\n            <a>Decision</a>.</p>\n         <p>The duration is specified in seconds, an integer greater than or equal to\n        <code>0</code>. You can use <code>NONE</code> to specify unlimited duration.</p>"}))
    RegisterActivityTypeInput.add_member(:default_task_schedule_to_close_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: DurationInSecondsOptional, location_name: 'defaultTaskScheduleToCloseTimeout', traits: {"smithy.api#documentation" => "<p>If set, specifies the default maximum duration for a task of this activity type. This\n      default can be overridden when scheduling an activity task using the\n        <code>ScheduleActivityTask</code>\n            <a>Decision</a>.</p>\n         <p>The duration is specified in seconds, an integer greater than or equal to\n        <code>0</code>. You can use <code>NONE</code> to specify unlimited duration.</p>"}))
