    RegisterDomainInput.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: DomainName, location_name: 'name', traits: {"smithy.api#documentation" => "<p>Name of the domain to register. The name must be unique in the region that the domain\n      is registered in.</p>\n         <p>The specified string must not start or end with whitespace. It must not contain a\n        <code>:</code> (colon), <code>/</code> (slash), <code>|</code> (vertical bar), or any\n      control characters (<code>\\u0000-\\u001f</code> | <code>\\u007f-\\u009f</code>). Also, it must\n      <i>not</i> be the literal string <code>arn</code>.</p>", "smithy.api#required" => {}}))
    RegisterDomainInput.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: Description, location_name: 'description', traits: {"smithy.api#documentation" => "<p>A text description of the domain.</p>"}))
    RegisterDomainInput.add_member(:workflow_execution_retention_period_in_days, Smithy::Schema::Shapes::ShapeRef.new(shape: DurationInDays, location_name: 'workflowExecutionRetentionPeriodInDays', traits: {"smithy.api#documentation" => "<p>The duration (in days) that records and histories of workflow executions on the domain\n      should be kept by the service. After the retention period, the workflow execution isn't\n      available in the results of visibility calls.</p>\n         <p>If you pass the value <code>NONE</code> or <code>0</code> (zero), then the workflow\n      execution history isn't retained. As soon as the workflow execution completes, the execution\n      record and its history are deleted.</p>\n         <p>The maximum workflow execution retention period is 90 days. For more information about\n      Amazon SWF service limits, see: <a href=\"https://docs.aws.amazon.com/amazonswf/latest/developerguide/swf-dg-limits.html\">Amazon SWF Service Limits</a> in the\n        <i>Amazon SWF Developer Guide</i>.</p>", "smithy.api#required" => {}}))
