    RegisterWorkflowTypeInput.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'name', traits: {"smithy.api#documentation" => "<p>The name of the workflow type.</p>\n         <p>The specified string must not contain a\n        <code>:</code> (colon), <code>/</code> (slash), <code>|</code> (vertical bar), or any\n      control characters (<code>\\u0000-\\u001f</code> | <code>\\u007f-\\u009f</code>). Also, it must\n      <i>not</i> be the literal string <code>arn</code>.</p>", "smithy.api#required" => {}}))
    RegisterWorkflowTypeInput.add_member(:version, Smithy::Schema::Shapes::ShapeRef.new(shape: Version, location_name: 'version', traits: {"smithy.api#documentation" => "<p>The version of the workflow type.</p>\n         <note>\n            <p>The workflow type consists of the name and version, the combination of which must be\n        unique within the domain. To get a list of all currently registered workflow types, use the\n          <a>ListWorkflowTypes</a> action.</p>\n         </note>\n         <p>The specified string must not contain a\n        <code>:</code> (colon), <code>/</code> (slash), <code>|</code> (vertical bar), or any\n      control characters (<code>\\u0000-\\u001f</code> | <code>\\u007f-\\u009f</code>). Also, it must\n      <i>not</i> be the literal string <code>arn</code>.</p>", "smithy.api#required" => {}}))
