    RespondDecisionTaskCompletedInput.add_member(:task_list_schedule_to_start_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: DurationInSecondsOptional, location_name: 'taskListScheduleToStartTimeout', traits: {"smithy.api#documentation" => "<p>Specifies a timeout (in seconds) for the task list override. When this parameter is missing, the task list override is permanent. This parameter makes it possible to temporarily override the task list. If a decision task scheduled on the override task list is not started within the timeout, the decision task will time out. Amazon SWF will revert the override and schedule a new decision task to the original task list.</p>\n         <p>If a decision task scheduled on the override task list is started within the timeout, but not completed within the start-to-close timeout, Amazon SWF will also revert the override and schedule a new decision task to the original task list.</p>"}))
