    ScheduleActivityTaskDecisionAttributes.add_member(:activity_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ActivityId, location_name: 'activityId', traits: {"smithy.api#documentation" => "<p>\n         The <code>activityId</code> of the activity task.</p>\n         <p>The specified string must not contain a\n        <code>:</code> (colon), <code>/</code> (slash), <code>|</code> (vertical bar), or any\n      control characters (<code>\\u0000-\\u001f</code> | <code>\\u007f-\\u009f</code>). Also, it must\n      <i>not</i> be the literal string <code>arn</code>.</p>", "smithy.api#required" => {}}))
